    D.shapeName = design.shape || 'square';
    growth(D, big ? Math.floor((CAP_N - w * 2) / 2) : Math.floor((N - w) / 2), big ? Math.floor((CAP_N - 22) / 2) : 4, big ? 2 : 1);
