  // ---------- letters that drop ----------
  // A letter lying in the world (the engine's Pickup) as a game sprite: Gilded in the full 18-row capital with its
  // glint passing over it, Painted at 14 rows (the capital cut down by its commonest colour, so the busy grounds still
  // read), the rest keep art.js's small tile. Colours are private chars (DROP_PALETTE) the engine adds to the palette.
  const DROP_CHARS = {};
  const DROP_PALETTE = {};
  Object.keys(MS).forEach((k, i) => { DROP_CHARS[k] = String.fromCharCode(0xe000 + i); DROP_PALETTE[DROP_CHARS[k]] = MS[k]; });
  const DROP_PAINTED = 14;
