      'GBBBBBBBBBBBBBBBBBBBBBqBG',
      'GBBBBBBBBBPVPeBBBBGBBBBBG',
      'GBBBBBBBBPePVBBBBBBBBBBBG',
      'GBBBBBBBeBPPBBBBBBBBBBBBG',
      'GBBBBBBPPPBBBBBGBBBBBBBBG',
      'GBBBBBPrPPBBBBBGBBBBPBBBG',
      'GBBBBVPPPPBBBBBBBBBPzPBBG',
