      'GBBBBBBkdddrZBBBBBBBBBBBBG',
      'GBBBBBBdzrggZBBBBBBBGBBBBG',
      'GBBBBBrZzqqgBBBBBBBBdBBBBG',
      'GBGBBBkrzZgzBBBBBBBBBBBBBG',
      'GBBBBBddzZzBBBBeBBBBBBBGBG',
      'GBBBBZzdZrkBBBPPZkkkBBBBBG',
      'GBBBBddddzzBBPRPPPPqkBBBBG',
      'GBBBZdZddrrBkPPgPqPzdBBBBG',
      'GGBBrdZddZZZgoPGPPrdZBBBBG',
      'GBBBzdZrdddrGqqPPrdrBBBBBG',
      'GBBBzdzZrddZqPPPrdrrBBBBBG',
      'GBBBrZzrZkezzzzrdrrrBBGBBG',
      'GBBkzdZdzrZkBZrdrzzzBBBBBG',
